MOD = 1000000007

def geometricSumMod(r, n):
    r %= MOD

    def go(k):
        # returns (S(k), r^k) modulo MOD
        if k == 0:
            return 0, 1
        if k % 2 == 1:
            s, pw = go(k - 1)
            return (s + pw) % MOD, pw * r % MOD
        s, pw = go(k // 2)
        return (s + pw * s) % MOD, pw * pw % MOD

    return go(n)[0]
